import{_ as t,a as r,o as a,a6 as i}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"URL Rewrites","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/search-seo/url-rewrites/index.md","filePath":"api/rest-api/admin/marketing/search-seo/url-rewrites/index.md","lastUpdated":1786429091000}'),o={name:"api/rest-api/admin/marketing/search-seo/url-rewrites/index.md"};function s(n,e,d,l,h,c){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="url-rewrites" tabindex="-1">URL Rewrites <a class="header-anchor" href="#url-rewrites" aria-label="Permalink to &quot;URL Rewrites&quot;">​</a></h1><p>A <strong>URL rewrite</strong> sends a shopper who requests one path to a different target path — a manual redirect you control. It mirrors the admin <strong>Marketing → Search &amp; SEO → URL Rewrites</strong> screen.</p><h2 id="how-a-url-rewrite-works" tabindex="-1">How a URL rewrite works <a class="header-anchor" href="#how-a-url-rewrite-works" aria-label="Permalink to &quot;How a URL rewrite works&quot;">​</a></h2><p>A rewrite maps a <strong>source path</strong> to a <strong>target path</strong> for a given storefront entity and locale.</p><ul><li><strong>What it points at</strong> — <code>entityType</code> ties the rewrite to a <code>product</code>, <code>category</code>, or <code>cms_page</code>. <code>requestPath</code> is the path a shopper requests; <code>targetPath</code> is where they end up.</li><li><strong>How it redirects</strong> — <code>redirectType</code> is either <code>301</code> (permanent) or <code>302</code> (temporary). A <code>301</code> tells search engines the move is permanent and transfers ranking; a <code>302</code> signals a temporary detour.</li><li><strong>Where it applies</strong> — <code>locale</code> scopes the rewrite to a single storefront locale.</li></ul><p><strong>Why it matters.</strong> When a slug changes — a renamed product, a moved category, an updated CMS page — old bookmarks and search-engine links would otherwise break. A rewrite keeps those links alive by forwarding them to the new path.</p><p><strong>Relation to other menus.</strong> Bagisto also creates rewrites automatically when a slug changes. The entries here are the ones you add or adjust by hand, complementing those automatic rewrites.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites-list.html">List</a></td><td><code>GET /api/admin/marketing/url-rewrites</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/url-rewrites/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites-create.html">Create</a></td><td><code>POST /api/admin/marketing/url-rewrites</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites-update.html">Update</a></td><td><code>PUT /api/admin/marketing/url-rewrites/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/url-rewrites/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites-mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/marketing/url-rewrites/mass-delete</code></td></tr></tbody></table><p>All URL Rewrites endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const u=t(o,[["render",s]]);export{m as __pageData,u as default};
